package com.musteritakipcrm.alarm;

import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.content.res.ColorStateList;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.*;import android.speech.RecognizerIntent;import android.text.InputFilter;import android.text.InputType;import android.view.*;import android.widget.*;import java.security.MessageDigest;import java.text.SimpleDateFormat;import java.util.*;

public class MainActivity extends Activity{
 private static final String PREF="crm_alarm",M2="\u2063\u200B",M3="\u2063\u200C";private static final int REQ_SPEECH=51,REQ_PHOTO=52;private LinearLayout body,list;private int page=1;private boolean archive=false,n3Unlocked=false;private String calendarDay="";private List<Api.Entry> cache=new ArrayList<>();private final Set<Integer> openNotes=new HashSet<>();private EditText speechTarget;private ImageView photoPreview;private Uri selectedPhoto;private String photoOldKey="";
 @Override public void onCreate(Bundle b){super.onCreate(b);AlarmRingingService.ensureChannels(this);requestPermissionsIfNeeded();setContentView(ui());if(token().isEmpty())pairDialog();else{startServiceNow();load();}}
 private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}private LinearLayout v(){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);return x;}private TextView t(String s,float z,boolean bold){TextView x=new TextView(this);x.setText(s);x.setTextSize(z);x.setTextColor(Color.BLACK);if(bold)x.setTypeface(null,Typeface.BOLD);x.setPadding(dp(5),dp(2),dp(5),dp(2));return x;}
 private LinearLayout ui(){LinearLayout root=v();root.setBackgroundColor(Color.rgb(242,246,250));TextView h=t("📝 AJANDAM",20,true);h.setGravity(Gravity.CENTER);h.setPadding(dp(18),dp(13),dp(18),dp(13));h.setBackgroundColor(Color.rgb(255,202,40));root.addView(h);body=v();body.setPadding(dp(8),dp(5),dp(8),dp(8));root.addView(body,new LinearLayout.LayoutParams(-1,-1));buildPage();return root;}
 private void buildPage(){body.removeAllViews();LinearLayout nav=new LinearLayout(this);String[] n={"NOT 1","NOT 2","🔒 NOT 3","📅 TAKVİM"};for(int i=0;i<4;i++){final int p=i+1;Button b=new Button(this);b.setText(n[i]);b.setTextSize(9);b.setOnClickListener(x->openPage(p));nav.addView(b,new LinearLayout.LayoutParams(0,-2,1));}body.addView(nav);LinearLayout tools=new LinearLayout(this);Button add=new Button(this);add.setText("+ YENİ NOT");add.setTextSize(11);add.setOnClickListener(x->{if(connected())editForm(null,page==4?1:page,calendarDay);});Button meet=new Button(this);meet.setText("🎙 TOPLANTI");meet.setTextSize(10);meet.setOnClickListener(x->{if(connected())startActivity(new Intent(this,MeetingActivity.class));});Button arc=new Button(this);arc.setText(archive?"✓ ARŞİV":"ARŞİV");arc.setTextSize(10);arc.setOnClickListener(x->{archive=!archive;buildPage();if(page==4)renderCalendar();else render(cache);});tools.addView(add,new LinearLayout.LayoutParams(0,-2,1));tools.addView(meet,new LinearLayout.LayoutParams(0,-2,1));tools.addView(arc,new LinearLayout.LayoutParams(0,-2,1));body.addView(tools);if(page==4){renderCalendar();return;}ScrollView sc=new ScrollView(this);list=v();sc.addView(list);body.addView(sc,new LinearLayout.LayoutParams(-1,0,1));if(token().isEmpty())pairDialog();else render(cache);}
 private void openPage(int p){if(p==3&&!n3Unlocked){pinDialog();return;}if(page==3&&p!=3)n3Unlocked=false;page=p;archive=false;openNotes.clear();buildPage();if(p!=4)load();else if(cache.isEmpty())load();}
 private String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());}private boolean visibleMain(Api.Entry e){return!e.archived()||e.date.compareTo(today())>=0;}private boolean visibleArchive(Api.Entry e){return e.archived()&&e.date.compareTo(today())<0;}
 private void render(List<Api.Entry>a){if(list==null)return;list.removeAllViews();int n=0;for(Api.Entry e:a){if(cat(e)!=page)continue;if(archive?!visibleArchive(e):!visibleMain(e))continue;n++;list.addView(entryRow(e,n),rowParams());}if(n==0)list.addView(t(archive?"Arşiv boş.":"Henüz kayıt yok.",12,false));}
 private int pastel(int i){int[] c={Color.rgb(255,248,210),Color.rgb(225,244,255),Color.rgb(238,229,255),Color.rgb(226,248,231),Color.rgb(255,232,224),Color.rgb(255,238,249),Color.rgb(231,245,240)};return c[Math.abs(i-1)%c.length];}
 private View entryRow(Api.Entry e,int row){LinearLayout outer=new LinearLayout(this);outer.setOrientation(LinearLayout.HORIZONTAL);outer.setGravity(Gravity.CENTER_VERTICAL);GradientDrawable bg=new GradientDrawable();bg.setColor(pastel(row));bg.setCornerRadius(dp(11));bg.setStroke(dp(1),Color.rgb(155,185,198));outer.setBackground(bg);outer.setPadding(dp(3),dp(1),dp(3),dp(1));CheckBox done=new CheckBox(this);done.setChecked(e.archived());if(Build.VERSION.SDK_INT>=21)done.setButtonTintList(new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{Color.rgb(62,185,145),Color.rgb(145,160,170)}));done.setOnClickListener(x->archive(e,done.isChecked()));outer.addView(done,new LinearLayout.LayoutParams(dp(42),dp(42)));LinearLayout mid=v();TextView title=t(titleOf(e.note),13,true);title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);mid.addView(title);if(openNotes.contains(e.id)){String d=detailOf(e.note);if(!d.isEmpty()){TextView desc=t(d,11.5f,false);mid.addView(desc);}String ph=photoFor(e);if(!ph.isEmpty()){TextView pic=t("📷 Resim eklendi",9,false);pic.setTextColor(Color.rgb(40,110,160));mid.addView(pic);}}mid.setOnClickListener(x->{if(openNotes.contains(e.id))openNotes.remove(e.id);else openNotes.add(e.id);render(cache);});outer.addView(mid,new LinearLayout.LayoutParams(0,-2,1));TextView menu=t("⋮",22,true);menu.setGravity(Gravity.CENTER);GradientDrawable mbg=new GradientDrawable();mbg.setColor(Color.argb(90,255,255,255));mbg.setCornerRadius(dp(9));menu.setBackground(mbg);menu.setOnClickListener(x->showEntryMenu(e,menu));outer.addView(menu,new LinearLayout.LayoutParams(dp(40),dp(42)));return outer;}
 private View entryRow(Api.Entry e){int pos=1;for(Api.Entry x:cache){if(x.id==e.id)break;pos++;}return entryRow(e,pos);}
 private LinearLayout.LayoutParams rowParams(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(2),0,dp(2));return p;}
 private void showEntryMenu(Api.Entry e,View a){PopupMenu p=new PopupMenu(this,a);p.getMenu().add("Düzenle");if(!e.remindAt.isEmpty())p.getMenu().add("⏰ Alarm: "+dayMonthSlash(e.date)+" "+timeOnly(e.remindAt));p.getMenu().add("📷 Resim Ekle / Değiştir");if(!photoFor(e).isEmpty())p.getMenu().add("🖼 Resmi Gör");p.getMenu().add("Panoya Ekle");p.getMenu().add("✉ Mail Gönder");p.getMenu().add(e.archived()?"Arşivden Çıkar":"Arşive Al");p.getMenu().add("Sil");p.setOnMenuItemClickListener(m->{String s=m.getTitle().toString();if(s.equals("Düzenle")||s.startsWith("⏰"))editForm(e,cat(e),"");else if(s.startsWith("📷"))pickPhotoFor(e);else if(s.startsWith("🖼"))showPhoto(e);else if(s.equals("Panoya Ekle"))copyToClipboard(titleOf(e.note),detailOf(e.note));else if(s.equals("✉ Mail Gönder"))mail(e);else if(s.equals("Sil"))delete(e);else archive(e,!e.archived());return true;});p.show();}
 private String photoKey(Api.Entry e){return"photo_"+hash(e.date+"|"+clean(e.note));}private String photoFor(Api.Entry e){return getSharedPreferences(PREF,MODE_PRIVATE).getString(photoKey(e),"");}
 private void pickPhotoFor(Api.Entry e){photoOldKey=photoKey(e);selectedPhoto=null;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(i,REQ_PHOTO);}catch(Exception x){show("Galeri açılamadı.");}}
 private void showPhoto(Api.Entry e){String s=photoFor(e);if(s.isEmpty())return;ImageView im=new ImageView(this);im.setAdjustViewBounds(true);im.setImageURI(Uri.parse(s));new AlertDialog.Builder(this).setTitle(titleOf(e.note)).setView(im).setPositiveButton("KAPAT",null).show();}
 private void mail(Api.Entry e){String ph=photoFor(e);Intent i=new Intent(Intent.ACTION_SEND);i.setType(ph.isEmpty()?"text/plain":"image/*");i.putExtra(Intent.EXTRA_SUBJECT,titleOf(e.note));i.putExtra(Intent.EXTRA_TEXT,titleOf(e.note)+(detailOf(e.note).isEmpty()?"":"\n\n"+detailOf(e.note)));if(!ph.isEmpty()){Uri u=Uri.parse(ph);i.putExtra(Intent.EXTRA_STREAM,u);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);}startActivity(Intent.createChooser(i,"Mail gönder"));}
 private void editForm(Api.Entry e,int category,String forced){LinearLayout form=v();form.setPadding(dp(20),0,dp(20),0);EditText title=new EditText(this);title.setHint("Başlık");title.setTextSize(15);title.setTypeface(null,Typeface.BOLD);title.setSingleLine(true);title.setText(e==null?"":titleOf(e.note));form.addView(title);EditText detail=new EditText(this);detail.setHint("Açıklama / not");detail.setTextSize(12.5f);detail.setMinLines(3);detail.setText(e==null?"":detailOf(e.note));form.addView(detail);LinearLayout actions=new LinearLayout(this);Button voice=new Button(this);voice.setText("🎙 SES");voice.setTextSize(9);voice.setOnClickListener(x->speechNote(detail));Button photo=new Button(this);photo.setText("📷 RESİM");photo.setTextSize(9);photo.setOnClickListener(x->{photoOldKey=e==null?"":photoKey(e);selectedPhoto=null;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,REQ_PHOTO);});Button paste=new Button(this);paste.setText("YAPIŞTIR");paste.setTextSize(9);paste.setOnClickListener(x->pasteFromClipboard(title,detail));actions.addView(voice,new LinearLayout.LayoutParams(0,-2,1));actions.addView(photo,new LinearLayout.LayoutParams(0,-2,1));actions.addView(paste,new LinearLayout.LayoutParams(0,-2,1));form.addView(actions);photoPreview=new ImageView(this);photoPreview.setAdjustViewBounds(true);photoPreview.setMaxHeight(dp(150));if(e!=null&&!photoFor(e).isEmpty())photoPreview.setImageURI(Uri.parse(photoFor(e)));form.addView(photoPreview,new LinearLayout.LayoutParams(-1,dp(120)));Calendar c=Calendar.getInstance();String initial=e!=null?e.date:forced;if(initial!=null&&!initial.isEmpty())try{c.setTime(new SimpleDateFormat("yyyy-MM-dd",Locale.US).parse(initial));}catch(Exception ignored){}final String[] day={fmt(c,"yyyy-MM-dd")};Button date=new Button(this);date.setText("📅 "+dayMonth(day[0]));date.setOnClickListener(x->new DatePickerDialog(this,(z,y,m,dd)->{c.set(y,m,dd);day[0]=fmt(c,"yyyy-MM-dd");date.setText("📅 "+dayMonth(day[0]));},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show());form.addView(date);LinearLayout tm=new LinearLayout(this);tm.setGravity(Gravity.CENTER);EditText hour=timeBox(),minute=timeBox();if(e!=null&&!e.remindAt.isEmpty()){String[]q=timeOnly(e.remindAt).split(":");if(q.length==2){hour.setText(q[0]);minute.setText(q[1]);}}tm.addView(t("⏰",18,false));tm.addView(hour,new LinearLayout.LayoutParams(dp(72),dp(50)));tm.addView(t(":",18,true));tm.addView(minute,new LinearLayout.LayoutParams(dp(72),dp(50)));form.addView(tm);AlertDialog dlg=new AlertDialog.Builder(this).setTitle(e==null?"Yeni Not":"Düzenle").setView(form).setNegativeButton("VAZGEÇ",null).setPositiveButton("KAYDET",null).create();dlg.setOnShowListener(x->{if(e==null){title.requestFocus();dlg.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE);}dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(z->{String bas=title.getText().toString().trim(),det=detail.getText().toString().trim(),hs=hour.getText().toString().trim(),ms=minute.getText().toString().trim();if(bas.isEmpty()){show("Başlık boş olamaz.");return;}String rem="";if(!hs.isEmpty()||!ms.isEmpty()){if(hs.isEmpty()||ms.isEmpty()){show("Saat ve dakikayı birlikte yazın.");return;}try{int h=Integer.parseInt(hs),m=Integer.parseInt(ms);if(h<0||h>23||m<0||m>59){show("Geçerli saat girin.");return;}rem=day[0]+" "+String.format(Locale.US,"%02d:%02d",h,m);}catch(Exception q){show("Geçerli saat girin.");return;}}String note=pack(category,bas+(det.isEmpty()?"":"\n"+det));String newKey="photo_"+hash(day[0]+"|"+clean(note));if(selectedPhoto!=null)getSharedPreferences(PREF,MODE_PRIVATE).edit().putString(newKey,selectedPhoto.toString()).apply();else if(e!=null&&!photoFor(e).isEmpty()&&!newKey.equals(photoKey(e)))getSharedPreferences(PREF,MODE_PRIVATE).edit().putString(newKey,photoFor(e)).apply();dlg.dismiss();if(e==null)save(day[0],note,rem);else update(e.id,day[0],note,rem);selectedPhoto=null;photoPreview=null;});});dlg.show();}
 private EditText timeBox(){EditText x=new EditText(this);x.setTextSize(17);x.setSingleLine(true);x.setGravity(Gravity.CENTER);x.setInputType(InputType.TYPE_CLASS_NUMBER);x.setFilters(new InputFilter[]{new InputFilter.LengthFilter(2)});GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(dp(8));g.setStroke(dp(1),Color.rgb(130,150,165));x.setBackground(g);return x;}
 private void speechNote(EditText target){speechTarget=target;Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"tr-TR");try{startActivityForResult(i,REQ_SPEECH);}catch(Exception e){show("Sesli yazma servisi bulunamadı.");}}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(c!=RESULT_OK||d==null)return;if(r==REQ_SPEECH&&speechTarget!=null){ArrayList<String>a=d.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(a!=null&&!a.isEmpty()){if(speechTarget.length()>0)speechTarget.append(" ");speechTarget.append(a.get(0));}}else if(r==REQ_PHOTO&&d.getData()!=null){Uri u=d.getData();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}selectedPhoto=u;if(!photoOldKey.isEmpty()){getSharedPreferences(PREF,MODE_PRIVATE).edit().putString(photoOldKey,u.toString()).apply();photoOldKey="";render(cache);}if(photoPreview!=null)photoPreview.setImageURI(u);}}
 private void copyToClipboard(String a,String b){((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("AJANDAM",a+(b.isEmpty()?"":"\n"+b)));show("Panoya eklendi.");}private void pasteFromClipboard(EditText a,EditText b){ClipboardManager cm=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);if(!cm.hasPrimaryClip()||cm.getPrimaryClip()==null)return;String s=String.valueOf(cm.getPrimaryClip().getItemAt(0).coerceToText(this));if(a.length()==0){int p=s.indexOf('\n');a.setText(p<0?s:s.substring(0,p));if(p>=0)b.setText(s.substring(p+1));}else b.append(s);}
 private String dayMonth(String d){try{return new SimpleDateFormat("dd.MM",Locale.US).format(new SimpleDateFormat("yyyy-MM-dd",Locale.US).parse(d));}catch(Exception x){return d;}}private String dayMonthSlash(String d){try{return new SimpleDateFormat("dd/MM",Locale.US).format(new SimpleDateFormat("yyyy-MM-dd",Locale.US).parse(d));}catch(Exception x){return d;}}private String timeOnly(String r){if(r==null)return"";String s=r.trim();int p=s.indexOf('T');if(p<0)p=s.indexOf(' ');if(p>=0&&p+1<s.length())s=s.substring(p+1);return s.length()>=5?s.substring(0,5):s;}
 private void renderCalendar(){if(body.getChildCount()>2)body.removeViews(2,body.getChildCount()-2);CalendarView cv=new CalendarView(this);cv.setFirstDayOfWeek(Calendar.MONDAY);body.addView(cv);TextView title=t("",13,true);body.addView(title);ScrollView sc=new ScrollView(this);list=v();sc.addView(list);body.addView(sc,new LinearLayout.LayoutParams(-1,0,1));if(calendarDay.isEmpty())calendarDay=today();showCalendarDay(title);cv.setOnDateChangeListener((x,y,m,d)->{calendarDay=String.format(Locale.US,"%04d-%02d-%02d",y,m+1,d);showCalendarDay(title);});}private void showCalendarDay(TextView title){title.setText("📅 "+dayMonth(calendarDay));list.removeAllViews();int row=0;for(Api.Entry e:cache)if(e.date.equals(calendarDay)&&(cat(e)!=3||n3Unlocked)&&(archive?visibleArchive(e):visibleMain(e)))list.addView(entryRow(e,++row),rowParams());}
 private int cat(Api.Entry e){return e.note.startsWith(M2)?2:e.note.startsWith(M3)?3:1;}private String clean(String n){return n.startsWith(M2)||n.startsWith(M3)?n.substring(2):n;}private String pack(int c,String n){return c==2?M2+n:c==3?M3+n:n;}private String titleOf(String n){n=clean(n);int p=n.indexOf('\n');return(p<0?n:n.substring(0,p)).trim();}private String detailOf(String n){n=clean(n);int p=n.indexOf('\n');return p<0?"":n.substring(p+1).trim();}
 private void load(){if(token().isEmpty()){pairDialog();return;}new Thread(()->{try{List<Api.Entry>a=Api.agenda(token());runOnUiThread(()->{cache=a;if(page==4)buildPage();else render(a);});}catch(Exception e){runOnUiThread(()->show("Ajanda alınamadı: "+e.getMessage()));}}).start();}private void save(String d,String n,String r){new Thread(()->{try{Api.addEntry(token(),d,n,r);runOnUiThread(this::load);}catch(Exception e){runOnUiThread(()->show("Kaydedilemedi: "+e.getMessage()));}}).start();}private void update(int id,String d,String n,String r){new Thread(()->{try{Api.updateEntry(token(),id,d,n,r);runOnUiThread(this::load);}catch(Exception e){runOnUiThread(()->show("Güncellenemedi: "+e.getMessage()));}}).start();}private void archive(Api.Entry e,boolean a){new Thread(()->{try{Api.archive(token(),e.id,a);runOnUiThread(this::load);}catch(Exception x){runOnUiThread(()->show(x.getMessage()));}}).start();}private void delete(Api.Entry e){new AlertDialog.Builder(this).setTitle("Notu Sil").setMessage("Bu not silinsin mi?").setNegativeButton("HAYIR",null).setPositiveButton("SİL",(d,w)->new Thread(()->{try{Api.deleteEntry(token(),e.id);runOnUiThread(this::load);}catch(Exception x){runOnUiThread(()->show(x.getMessage()));}}).start()).show();}
 private void pinDialog(){String saved=getSharedPreferences(PREF,MODE_PRIVATE).getString("n3_pin","");EditText pin=new EditText(this);pin.setHint(saved.isEmpty()?"4 haneli PIN belirleyin":"PIN girin");pin.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);AlertDialog d=new AlertDialog.Builder(this).setTitle("NOT 3 - Özel").setView(pin).setNegativeButton("VAZGEÇ",null).setPositiveButton("AÇ",null).create();d.setOnShowListener(z->d.getButton(-1).setOnClickListener(x->{String s=pin.getText().toString().trim();if(s.length()!=4){show("4 haneli PIN girin.");return;}String h=hash(s);if(saved.isEmpty())getSharedPreferences(PREF,MODE_PRIVATE).edit().putString("n3_pin",h).apply();else if(!saved.equals(h)){show("PIN yanlış.");return;}n3Unlocked=true;page=3;d.dismiss();buildPage();load();}));d.show();}
 private String hash(String s){try{byte[]b=MessageDigest.getInstance("SHA-256").digest(s.getBytes("UTF-8"));StringBuilder x=new StringBuilder();for(byte q:b)x.append(String.format(Locale.US,"%02x",q));return x.toString();}catch(Exception e){return s;}}private String fmt(Calendar c,String p){return new SimpleDateFormat(p,Locale.US).format(c.getTime());}
 private boolean connected(){if(!token().isEmpty())return true;pairDialog();return false;}private void pairDialog(){if(list==null)return;list.removeAllViews();list.addView(t("Site ajandanızla bağlantı yapın.",13,true));Button b=new Button(this);b.setText("SİTEYE BAĞLAN");b.setOnClickListener(v->showCodeDialog());list.addView(b);}private void showCodeDialog(){EditText code=new EditText(this);code.setHint("6 haneli kod");code.setInputType(InputType.TYPE_CLASS_NUMBER);AlertDialog d=new AlertDialog.Builder(this).setTitle("AJANDAM'ı Bağla").setView(code).setNegativeButton("VAZGEÇ",null).setPositiveButton("BAĞLA",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{String c=code.getText().toString().trim();if(c.length()!=6){show("6 haneli kodu girin.");return;}new Thread(()->{try{String tok=Api.pair(c,"AJANDAM");getSharedPreferences(PREF,MODE_PRIVATE).edit().putString("token",tok).apply();runOnUiThread(()->{d.dismiss();startServiceNow();load();});}catch(Exception e){runOnUiThread(()->show("Bağlantı olmadı: "+e.getMessage()));}}).start();}));d.show();}
 private String token(){return getSharedPreferences(PREF,MODE_PRIVATE).getString("token","");}private void show(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}private void startServiceNow(){Intent i=new Intent(this,SyncService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}private void requestPermissionsIfNeeded(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},20);}
}
